import path from 'node:path';

const GB = 1024 ** 3;

function bytes(name, fallback) {
  const raw = process.env[name];
  if (!raw) return fallback;
  const m = /^(\d+(?:\.\d+)?)\s*([KMGT]?)B?$/i.exec(raw.trim());
  if (!m) throw new Error(`${name}: cannot parse "${raw}" as a size (e.g. 10G)`);
  const unit = { '': 1, K: 1024, M: 1024 ** 2, G: GB, T: 1024 ** 4 }[m[2].toUpperCase()];
  return Math.floor(Number(m[1]) * unit);
}

const dataDir = process.env.DATA_DIR || '/data';

export const config = {
  port: Number(process.env.PORT || 3000),
  dataDir,
  uploadsDir: path.join(dataDir, 'uploads'),
  batchesDir: path.join(dataDir, 'batches'),
  // A file that must exist in DATA_DIR. If the volume behind it is not mounted, the
  // marker is missing and the app refuses uploads instead of filling whatever disk
  // happens to sit under the mount point.
  markerFile: path.join(dataDir, '.drop-volume'),
  requireMarker: process.env.REQUIRE_MARKER !== '0',
  publicUrl: (process.env.PUBLIC_URL || '').replace(/\/+$/, ''),
  appriseUrl: process.env.APPRISE_URL || '',
  appriseTag: process.env.APPRISE_TAG || 'email',
  maxFileSize: bytes('MAX_FILE_SIZE', 50 * GB),
  // Upper bound for everything stored here, finished or in flight.
  maxTotal: bytes('MAX_TOTAL', 500 * GB),
  // Uploads are refused if accepting one would leave less than this free on the volume.
  minFree: bytes('MIN_FREE', 300 * GB),
  maxFilesPerBatch: Number(process.env.MAX_FILES_PER_BATCH || 200),
  // A batch whose uploader never pressed "done" (closed the tab) is announced after
  // this much silence, so nothing that finished goes unnoticed.
  idleNotifyMs: Number(process.env.IDLE_NOTIFY_MINUTES || 30) * 60_000,
  // Half-finished uploads nobody resumed are removed after this long.
  staleUploadMs: Number(process.env.STALE_UPLOAD_DAYS || 7) * 86_400_000,
  sweepIntervalMs: 5 * 60_000,
  // Home mode: where the server asks for its own public address (empty turns home
  // mode off), and how often a mismatching visitor may make it ask again.
  homeLookupUrl: process.env.HOME_LOOKUP_URL ?? 'https://1.1.1.1/cdn-cgi/trace',
  homeRecheckMs: Number(process.env.HOME_RECHECK_SECONDS || 60) * 1000,
  shareDays: [1, 7, 30],
  maxSharesPerBatch: 20,
};
# Runs behind a reverse proxy on an existing Docker network. Everything
# deployment-specific (data directory, network, URLs) comes from the environment
# the stack is deployed with; nothing host-specific lives here.
services:
  drop:
    build: .
    image: drop:local
    container_name: drop
    restart: unless-stopped
    # No published port: the reverse proxy reaches the app over a shared network,
    # so nothing can bypass it (and spoof CF-Connecting-IP).
    networks:
      - frontend
    environment:
      - TZ=Europe/Budapest
      - PUBLIC_URL=${PUBLIC_URL:?set PUBLIC_URL}
      - APPRISE_URL=${APPRISE_URL:-}
      - APPRISE_TAG=${APPRISE_TAG:-email}
      - MAX_FILE_SIZE=${MAX_FILE_SIZE:-50G}
      - MAX_TOTAL=${MAX_TOTAL:-500G}
      - MIN_FREE=${MIN_FREE:-300G}
    volumes:
      # Absolute host path, writable by uid 1000 (the image's `node` user), with a
      # `.drop-volume` marker file at its root.
      - ${DROP_DATA_DIR:?set DROP_DATA_DIR}:/data
    read_only: true
    tmpfs:
      - /tmp
    security_opt:
      - no-new-privileges:true
    cap_drop:
      - ALL

networks:
  frontend:
    # The reverse proxy's network; created by the proxy's own stack.
    name: ${DROP_NETWORK:?set DROP_NETWORK}
    external: true
# drop on its own: the app, a Cloudflare Tunnel to reach it, and an Apprise API
# server for the emails. Nothing is published on the host; the tunnel is the only
# way in. Copy .env.example to .env and apprise/apprise.yml.example to
# apprise/apprise.yml, fill both in, then `docker compose up -d --build`.
#
# Not tested as a whole: a starting point, not a recipe. The repo's top-level
# compose.yaml is the one in production, behind an existing reverse proxy.
services:
  drop:
    build: ../..
    image: drop:local
    restart: unless-stopped
    environment:
      - TZ=${TZ:-UTC}
      - PUBLIC_URL=${PUBLIC_URL:?set PUBLIC_URL}
      - APPRISE_URL=http://apprise:8000/notify/apprise
      - APPRISE_TAG=email
      - MAX_FILE_SIZE=${MAX_FILE_SIZE:-10G}
      - MAX_TOTAL=${MAX_TOTAL:-100G}
      - MIN_FREE=${MIN_FREE:-20G}
    volumes:
      - drop-data:/data
    depends_on:
      drop-init:
        condition: service_completed_successfully
    read_only: true
    tmpfs:
      - /tmp
    security_opt:
      - no-new-privileges:true
    cap_drop:
      - ALL

  # A fresh named volume is root-owned and empty. Hand it to the image's `node`
  # user (uid 1000) and add the marker drop insists on before it writes anything.
  drop-init:
    image: busybox:1.37
    command: sh -c 'chown 1000:1000 /data && touch /data/.drop-volume && chown 1000:1000 /data/.drop-volume'
    volumes:
      - drop-data:/data
    restart: "no"

  # In the Cloudflare dashboard, give the tunnel a public hostname (the host in
  # PUBLIC_URL) with service http://drop:3000. Going through Cloudflare is not
  # optional: home mode and the per-IP limits read CF-Connecting-IP.
  cloudflared:
    image: cloudflare/cloudflared:latest
    restart: unless-stopped
    command: tunnel --no-autoupdate run
    environment:
      - TUNNEL_TOKEN=REDACTED TUNNEL_TOKEN}
    depends_on:
      - drop

  # Stateful "simple" mode: apprise/apprise.yml is the config for the key
  # `apprise`, which is the /notify/apprise in drop's APPRISE_URL.
  apprise:
    image: caronc/apprise:latest
    restart: unless-stopped
    environment:
      - TZ=${TZ:-UTC}
      - APPRISE_STATEFUL_MODE=simple
      - APPRISE_WORKER_COUNT=1
    volumes:
      - ./apprise:/config

volumes:
  drop-data:
# The address people will use; the tunnel's public hostname must match it.
PUBLIC_URL=https://drop.example.com

# Cloudflare dashboard → Zero Trust → Networks → Tunnels → your tunnel → the token
# in its `cloudflared tunnel run --token …` command.
TUNNEL_TOKEN=

TZ=UTC

# Largest file; everything stored, uploads in progress included; and the free
# space no upload may eat into. Sized for the disk behind the Docker volume.
MAX_FILE_SIZE=10G
MAX_TOTAL=100G
MIN_FREE=20G
